"""Collect Mantle secrets and persist them to the project's `.env` file.

Ported from the standalone `rasa-init` wizard package
(`packages/rasa-init/src/rasa_init/secrets.py`) so `rasa init --engine
mantle` does not depend on that package. Secret values are never accepted
via CLI flags: they come from the environment (reused when already exported)
or from hidden interactive prompts.
"""

from __future__ import annotations

import getpass
import os
import tempfile
from pathlib import Path
from typing import Callable, Dict, List, Mapping, MutableMapping, Optional, Text

import structlog

from rasa.shared.constants import OPENAI_API_KEY_ENV_VAR
from rasa.shared.utils.cli import print_error, print_info, print_success, print_warning

structlogger = structlog.get_logger(__name__)

LICENSE_URL = "https://rasa.com/rasa-pro-developer-edition-license-key-request/"


def collect_secrets(
    *,
    assume_yes: bool,
    environ: Optional[Mapping[Text, Text]] = None,
    getpass_fn: Optional[Callable[[Text], Text]] = None,
) -> Dict[Text, Text]:
    """Collect the Mantle secrets from the environment or interactive prompts.

    `RASA_LICENSE` is the canonical license env var; `RASA_PRO_LICENSE` is read
    as a fallback when `RASA_LICENSE` is unset (both are accepted as input, but
    only `RASA_LICENSE` is ever written back to `.env`). Values already present
    in the environment are reused without prompting. In non-interactive mode,
    any missing secret aborts `rasa init`.

    Args:
        assume_yes: Non-interactive mode (`--no-prompt`); missing secrets are
            fatal.
        environ: Environment mapping to read from; defaults to `os.environ`.
        getpass_fn: Hidden-input reader; defaults to `getpass.getpass`.

    Returns:
        Mapping of the canonical secret env-var name (`RASA_LICENSE`, never
        the legacy alias) to its value.

    Raises:
        SystemExit: code 2, in non-interactive mode, when secrets are missing.
    """
    # Deferred: `rasa.utils.licensing` pulls in `sanic`/`jwt`/telemetry, which
    # would slow down `rasa` CLI startup if imported at module level.
    from rasa.utils.licensing import LICENSE_ENV_VAR

    environ = os.environ if environ is None else environ
    getpass_fn = getpass.getpass if getpass_fn is None else getpass_fn
    secret_labels = {
        LICENSE_ENV_VAR: "Rasa Pro license key",
        OPENAI_API_KEY_ENV_VAR: "OpenAI API key",
    }

    collected: Dict[Text, Text] = {}
    missing: List[Text] = []
    for env_var, label in secret_labels.items():
        existing = _read_existing(env_var, environ)
        if existing:
            print_success(f"Reusing {env_var} from your environment.")
            collected[env_var] = existing
        elif assume_yes:
            missing.append(env_var)
        else:
            collected[env_var] = _prompt_secret(env_var, label, getpass_fn)

    if missing:
        _abort_missing(missing)
    return collected


def write_env_file(project_dir: Path, secret_values: Mapping[Text, Text]) -> Path:
    """Write `secret_values` to `<project_dir>/.env` with 0600 permissions.

    The file is created atomically with restrictive permissions (no
    open-then-chmod race). If a `.env` already exists, its keys are merged
    (values collected this run win) rather than being silently clobbered.

    Note: mode 0600 is meaningful on POSIX; on Windows, file ACLs govern
    access and this bit is largely cosmetic.

    Args:
        project_dir: Project directory to write `.env` into.
        secret_values: Mapping of env-var name to value.

    Returns:
        Path to the written `.env` file.
    """
    env_path = project_dir / ".env"
    values = dict(secret_values)
    try:
        fd = os.open(env_path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
    except FileExistsError:
        merged = {**_read_env(env_path), **values}
        _atomic_replace(env_path, _render_env(merged))
    else:
        with os.fdopen(fd, "w", encoding="utf-8") as handle:
            handle.write(_render_env(values))

    _announce_written(env_path)
    return env_path


def apply_secrets_to_environ(
    secret_values: Mapping[Text, Text],
    *,
    environ: Optional[MutableMapping[Text, Text]] = None,
) -> None:
    """Copy collected secrets into the process environment for in-process use.

    `write_env_file` only persists to disk. Subsequent steps of `rasa init`
    (validate, train, Inspector) run in the same process and read credentials
    from `os.environ`, so values typed at the interactive prompt must also be
    injected here. Existing non-empty environment values are left unchanged.

    Args:
        secret_values: Mapping of env-var name to value (blank values skipped).
        environ: Environment mapping to mutate; defaults to `os.environ`.
    """
    target: MutableMapping[Text, Text] = os.environ if environ is None else environ
    for key, value in secret_values.items():
        if not value:
            continue
        if target.get(key, "").strip():
            continue
        target[key] = value


def _read_existing(env_var: Text, environ: Mapping[Text, Text]) -> Text:
    """Read `env_var` from `environ`, falling back to the legacy license alias."""
    value = environ.get(env_var, "").strip()
    if value:
        return value

    from rasa.utils.licensing import LICENSE_ENV_VAR, LICENSE_ENV_VAR_LEGACY

    if env_var == LICENSE_ENV_VAR:
        return environ.get(LICENSE_ENV_VAR_LEGACY, "").strip()
    return ""


def _prompt_secret(
    env_var: Text, label: Text, getpass_fn: Callable[[Text], Text]
) -> Text:
    """Prompt for a single secret with hidden input, re-asking if left empty."""
    from rasa.utils.licensing import LICENSE_ENV_VAR

    if env_var == LICENSE_ENV_VAR:
        print_info("Request a free Rasa Pro Developer Edition license here:")
        print_info(f"    {LICENSE_URL}")
    for _ in range(3):
        value = getpass_fn(f"Enter your {label} (input hidden): ").strip()
        if value:
            return value
        print_warning(f"{label} cannot be empty.")
    print_warning(f"No {label} provided; its entry in .env will be blank.")
    return ""


def _abort_missing(missing: List[Text]) -> None:
    """Abort with exit code 2, naming the env vars the user must export."""
    joined = ", ".join(missing)
    print_error(f"Missing required secrets in non-interactive mode: {joined}")
    print_info("Export them before re-running, for example:")
    for env_var in missing:
        print_info(f"    export {env_var}=...")
    raise SystemExit(2)


def _announce_written(env_path: Path) -> None:
    """Print a POSIX-aware confirmation that `.env` was written."""
    if os.name == "nt":
        print_success(f"Wrote secrets to {env_path}.")
    else:
        print_success(f"Wrote secrets to {env_path} (permissions 0600).")


def _render_env(values: Mapping[Text, Text]) -> Text:
    """Render an ordered mapping as `KEY=value` lines with a trailing newline."""
    if not values:
        return ""
    return "\n".join(f"{key}={value}" for key, value in values.items()) + "\n"


def _read_env(env_path: Path) -> Dict[Text, Text]:
    """Parse an existing `.env` into a mapping, ignoring blanks and comments."""
    parsed: Dict[Text, Text] = {}
    for line in env_path.read_text(encoding="utf-8").splitlines():
        stripped = line.strip()
        if not stripped or stripped.startswith("#") or "=" not in stripped:
            continue
        key, _, value = stripped.partition("=")
        parsed[key.strip()] = value
    return parsed


def _atomic_replace(env_path: Path, content: Text) -> None:
    """Write `content` to a 0600 temp file, then atomically replace target."""
    handle = tempfile.NamedTemporaryFile(
        mode="w",
        encoding="utf-8",
        dir=str(env_path.parent),
        prefix=".env.",
        delete=False,
    )
    try:
        os.chmod(handle.name, 0o600)
        handle.write(content)
        handle.close()
        os.replace(handle.name, env_path)
    finally:
        if os.path.exists(handle.name):
            os.unlink(handle.name)
